from itertools import product

ORIENTATIONS = [
    ((0,0),(0,1),(0,2),(1,0),(1,2),(2,2)),
    ((0,1),(0,2),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(1,0),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,0),(2,0),(2,1)),
    ((0,2),(1,0),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,0),(1,2),(2,0)),
    ((0,0),(0,1),(1,0),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,2),(2,1),(2,2)),
]

def check_coloring(m, n, w_func, name=""):
    """Check if a coloring obstructs tiling of m x n."""
    H = m * n // 6
    S = sum(w_func(r, c) for r in range(m) for c in range(n))

    hook_sums = set()
    for tr in range(m - 2):
        for tc in range(n - 2):
            for orient in ORIENTATIONS:
                s = sum(w_func(tr+dr, tc+dc) for dr, dc in orient)
                hook_sums.add(s)

    # DP: can we sum H values from hook_sums to get S?
    reachable = {0}
    for _ in range(H):
        new = set()
        for s in reachable:
            for v in hook_sums:
                new.add(s + v)
        reachable = new

    if S not in reachable:
        print(f"OBSTRUCTION for {m}x{n} with {name}: S={S}, hook_sums={sorted(hook_sums)}, H={H}")
        return True
    return False

# Test the 2x2 block coloring: w(r,c) = (-1)^{floor(r/2)+floor(c/2)}
w_block = lambda r, c: (-1)**((r//2) + (c//2))

# Test for 6x6
check_coloring(6, 6, w_block, "2x2 blocks")

# Also try: w(r,c) = (-1)^{floor(r/2)} (row blocks only)
w_rowblock = lambda r, c: (-1)**(r//2)
check_coloring(6, 6, w_rowblock, "row blocks")

# w(r,c) = (-1)^{floor(c/2)} (col blocks only)
w_colblock = lambda r, c: (-1)**(c//2)
check_coloring(6, 6, w_colblock, "col blocks")

# Try all period-4 separable colorings with values in {-2,-1,0,1,2}
