found = False
for fv in product(range(-2, 3), repeat=4):
    for gv in product(range(-2, 3), repeat=4):
        w = lambda r, c, fv=fv, gv=gv: fv[r % 4] * gv[c % 4]
        if check_coloring(6, 6, w, f"f={fv}, g={gv}"):
            found = True
            break
