import numpy as np
from itertools import product

ORIENTATIONS = [
    ((0,0),(0,1),(0,2),(1,0),(1,2),(2,2)),
    ((0,1),(0,2),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(1,0),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,0),(2,0),(2,1)),
    ((0,2),(1,0),(1,2),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,0),(1,2),(2,0)),
    ((0,0),(0,1),(1,0),(2,0),(2,1),(2,2)),
    ((0,0),(0,1),(0,2),(1,2),(2,1),(2,2)),
]

def check_obstruction(m, n, w_grid):
    """Check if weight grid w_grid (period 4x4) obstructs tiling of m x n."""
    H = m * n // 6

    # Rectangle sum
    S = 0
    for r in range(m):
        for c in range(n):
            S += w_grid[r % 4][c % 4]

    if S == 0:
        return False  # trivially satisfiable

    # All possible hook sums
    hook_sums = set()
    for tr in range(m - 2):
        for tc in range(n - 2):
            for orient in ORIENTATIONS:
                s = sum(w_grid[(tr+dr) % 4][(tc+dc) % 4] for dr, dc in orient)
                hook_sums.add(s)

    # DP: can H values from hook_sums sum to S?
    reachable = {0}
    for _ in range(H):
        new = set()
        for s in reachable:
            for v in hook_sums:
                new.add(s + v)
        reachable = new
        # Early termination if set gets too large
        if len(reachable) > 100000:
            break

    return S not in reachable

# Search for 4x4 patterns with values in {-1, 0, 1} that obstruct 6x6
m, n = 6, 6
print(f"Searching for 4x4 weight patterns obstructing {m}x{n}...")
found = False
count = 0

# Try patterns with values in {-1, 0, 1}
for wvals in product([-1, 0, 1], repeat=16):
    count += 1
    if count % 500000 == 0:
        print(f"  Checked {count}/43046721...")

    w_grid = [list(wvals[i*4:(i+1)*4]) for i in range(4)]

    if check_obstruction(m, n, w_grid):
        print(f"OBSTRUCTION FOUND at iteration {count}!")
        print(f"  Pattern: {[wvals[i*4:(i+1)*4] for i in range(4)]}")

        # Compute details
        H = m * n // 6
        S = sum(w_grid[r % 4][c % 4] for r in range(m) for c in range(n))
        hook_sums = set()
        for tr in range(m - 2):
            for tc in range(n - 2):
                for orient in ORIENTATIONS:
                    s = sum(w_grid[(tr+dr) % 4][(tc+dc) % 4] for dr, dc in orient)
                    hook_sums.add(s)
        print(f"  S={S}, hook_sums={sorted(hook_sums)}, H={H}")
        found = True
        break

if not found:
    print(f"No obstruction found after checking {count} patterns")

    # Try with values in {-2, -1, 0, 1, 2} but only separable patterns
    print("\nTrying separable patterns with values in [-2,2]...")
    for fv in product(range(-2, 3), repeat=4):
        for gv in product(range(-2, 3), repeat=4):
            w_grid = [[fv[r]*gv[c] for c in range(4)] for r in range(4)]
            if check_obstruction(m, n, w_grid):
                print(f"OBSTRUCTION (separable): f={fv}, g={gv}")
                H = m * n // 6
                S = sum(w_grid[r % 4][c % 4] for r in range(m) for c in range(n))
                hook_sums = set()
                for tr in range(m - 2):
                    for tc in range(n - 2):
                        for orient in ORIENTATIONS:
                            s = sum(w_grid[(tr+dr) % 4][(tc+dc) % 4] for dr, dc in orient)
                            hook_sums.add(s)
                print(f"  S={S}, hook_sums={sorted(hook_sums)}, H={H}")
                found = True
                break
        if found:
            break
    if not found:
        print("No separable obstruction found either")
